VALUES ('ebbf23ae', 'M', 'Geometry and Trigonometry', 'Circles', 'Hard', 'A circle in the $xy$-plane has a diameter with endpoints $(2, 4)$ and $(2, 14)$. An equation of this circle is $(x-2)^{2} + (y-9)^{2} = r^{2}$, where $r$ is a positive constant. What is the value of $r$?', NULL, NULL, NULL, NULL, 'SPR', NULL, '{"corpus":"official-cb","file":"circles.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('69b0d79d', 'M', 'Geometry and Trigonometry', 'Circles', 'Hard', 'Point O is the center of the circle above, and the measure of $\angle OAB$ is $30^\circ$. If the length of $\overline{OC}$ is $18$, what is the length of arc $\widehat{AB}$?', NULL, '{"A":"$9\\pi$","B":"$12\\pi$","C":"$15\\pi$","D":"$18\\pi$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"circles.ndjson"}'::jsonb);
