INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('9bf4c545', 'M', 'Problem Solving and Data Analysis', 'Evaluating Statistical Claims: Observational Studies and Experiments', 'Easy', 'The members of a city council wanted to assess the opinions of all city residents
about converting an open field into a dog park. The council surveyed a sample of
500 city residents who own dogs. The survey showed that the majority of those
sampled were in favor of the dog park. Which of the following is true about the city
council’s survey?', NULL, '{"A":"It shows that the majority of city residents are in favor of the dog park.","B":"The survey sample should have included more residents who are dog owners.","C":"The survey sample should have consisted entirely of residents who do not own dogs.","D":"The survey sample is biased because it is not representative of all city residents."}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"evaluating-statistical-claims-observational-studies-and-experiments.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('82dfb646', 'M', 'Problem Solving and Data Analysis', 'Evaluating Statistical Claims: Observational Studies and Experiments', 'Easy', 'A market researcher selected 200 people at random from a group of people who
indicated that they liked a certain book. The 200 people were shown a movie based on
the book and then asked whether they liked or disliked the movie. Of those surveyed,
