VALUES ('b7e6394d', 'M', 'Algebra', 'Linear equations in one variable', 'Hard', 'Alan drives an average of $100$ miles each week. His car can travel an average of $25$ miles per gallon of gasoline. Alan would like to reduce his weekly expenditure on gasoline by $\$5$. Assuming gasoline costs $\$4$ per gallon, which equation can Alan use to determine how many fewer average miles, $m$, he should drive each week?', NULL, '{"A":"$\\frac{25}{4}m = 95$","B":"$\\frac{25}{4}m = 5$","C":"$\\frac{4}{25}m = 95$","D":"$\\frac{4}{25}m = 5$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-equations-in-one-variable.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('38bf4e04', 'M', 'Algebra', 'Linear equations in one variable', 'Hard', 'A factory makes $9$-inch, $7$-inch, and $4$-inch concrete screws. During a certain day, the number of $9$-inch concrete screws that the factory makes is $5$ times the number $n$ of $7$-inch concrete screws, and the number of $4$-inch concrete screws is $22$. During this day, the factory makes $100$ concrete screws total. Which equation represents this situation?', NULL, '{"A":"$9(5n) + 7n + 4(22) = 100$","B":"$9n + 7n + 4n = 100$","C":"$5n + 22 = 100$","D":"$6n + 22 = 100$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-equations-in-one-variable.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('f14484a5', 'M', 'Algebra', 'Linear equations in one variable', 'Hard', 'A manufacturing plant makes $10$-inch, $9$-inch, and $7$-inch frying pans. During a certain day, the number of $10$-inch frying pans that the manufacturing plant makes is $4$ times the number $n$ of $9$-inch frying pans it makes, and the number of $7$-inch frying pans it makes is $10$. During this day, the manufacturing plant makes $100$ frying pans total. Which equation represents this situation?', NULL, '{"A":"$10(4n) + 9n + 7(10) = 100$","B":"$10n + 9n + 7n = 100$","C":"$4n + 10 = 100$","D":"$5n + 10 = 100$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-equations-in-one-variable.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('2937ef4f', 'M', 'Algebra', 'Linear equations in one variable', 'Hard', 'Hector used a tool called an auger to remove corn from a storage bin at a constant rate. The bin contained $24{,}000$ bushels of corn when Hector began to use the auger. After $5$ hours of using the auger, $19{,}350$ bushels of corn remained in the bin. If the auger continues to remove corn at this rate, what is the total number of hours Hector will have been using the auger when $12{,}840$ bushels of corn remain in the bin?', NULL, '{"A":"$3$","B":"$7$","C":"$8$","D":"$12$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-equations-in-one-variable.ndjson"}'::jsonb);
