VALUES ('535fa6e6', 'M', 'Algebra', 'Linear equations in two variables', 'Easy', 'A store sells potatoes for $\$0.85$ per pound and celery for $\$1.20$ per pound. If $p$ represents the number of pounds of potatoes and $c$ represents the number of pounds of celery, which expression represents the total cost, in dollars, of $p$ pounds of potatoes and $c$ pounds of celery?', NULL, '{"A":"$0.85p + 1.20c$","B":"$0.85c + 1.20p$","C":"$(0.85 + 1.20)pc$","D":"$(0.85)(1.20)pc$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-equations-in-two-variables.ndjson"}'::jsonb);
