INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('7d6928bd', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'A cleaning service charges a fee for each office and for each home. Last month, the number of offices cleaned, $f$, and the number of homes cleaned, $h$, was at most 14. Which inequality represents this situation?', NULL, '{"A":"$f + h \\le 14$","B":"$f + h \\ge 14$","C":"$f - h \\le 14$","D":"$f - h \\ge 14$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('b64e2c7f', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'Monarch butterflies can only fly when their body temperature is at least $55.0^\circ$F. If a monarch butterfly''s current body temperature is $51.3^\circ$F, by at least how many degrees Fahrenheit must its body temperature increase before it can fly?', NULL, '{"A":"1.3","B":"3.7","C":"5.0","D":"6.3"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
