VALUES ('b75f7812', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'Maria rents a boat. She pays a fee of $\$60$ per hour and a $\$10$ fee for the course she chooses. She has no more than $\$280$ to spend. What is the maximum number of whole hours Maria can rent the boat?', NULL, NULL, NULL, NULL, 'SPR', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('208626df', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'The perimeter of a rectangle is at most 27 inches. The inequality $2\ell + 2w \le 27$ represents this situation, where $\ell$ is the length and $w$ is the width of the rectangle. Which statement is the best interpretation of $(\ell, w) = (8, 3)$ in this context?', NULL, '{"A":"A rectangle with a length of 8 inches and a width of 3 inches has a perimeter of at most 27 inches.","B":"A rectangle with a length of 8 inches and a width of 3 inches has a perimeter of exactly 27 inches.","C":"A rectangle with a length of 8 inches and a width of 3 inches has a perimeter of at least 27 inches.","D":"A rectangle with a length of 8 inches and a width of 3 inches does not have a perimeter of at most 27 inches."}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('f01ef454', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'A geologist has a collection of rocks that are all the same type and estimates that each rock weighs about 165 pounds per cubic foot. The geologist calculates that the volume of each rock is between 12.7 cubic feet and 15.7 cubic feet, inclusive. Which inequality represents all possible weights $w$, in pounds, of a rock in this collection?', NULL, '{"A":"$12.7 \\le w \\le 15.7$","B":"$165 \\le w \\le 177.7$","C":"$177.7 \\le w \\le 180.7$","D":"$2{,}095.5 \\le w \\le 2{,}590.5$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('e744499e', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'A teacher is ordering workbooks and flash cards for her students. Workbooks cost $\$3$ each and flash cards cost $\$4$ each. She wants to order at least 20 items and spend at most $\$80$. Which system of inequalities represents this situation, where $x$ represents the number of workbooks and $y$ represents the number of flash cards?', NULL, '{"A":"$x + y \\ge 20$ and $3x + 4y \\le 80$","B":"$x + y \\ge 20$ and $3x + 4y \\ge 80$","C":"$x + y \\le 20$ and $3x + 4y \\le 80$","D":"$x + y \\le 20$ and $3x + 4y \\ge 80$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('2869fe95', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'During a 3-week period, the temperature in a certain city ranged from $31^\circ$F to $67^\circ$F, inclusive. Which inequality represents all possible temperatures $t$, in degrees Fahrenheit, during this 3-week period?', NULL, '{"A":"$|t - 31| \\le 67$","B":"$|t + 31| \\le 67$","C":"$|t - 49| \\le 18$","D":"$|t + 49| \\le 18$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
