VALUES ('86f7483f', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'Dragonflies can travel anywhere from 1,510 miles to 4,130 miles during migration. Which of the following inequalities represents all possible distances $d$, in miles, a dragonfly can travel during migration?', NULL, '{"A":"$d \\le 1{,}510$","B":"$d \\ge 4{,}130$","C":"$1{,}510 \\le d \\le 4{,}130$","D":"$d \\le 1{,}510$ or $d \\ge 4{,}130$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('df32b09c', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'Tom scored 85, 78, and 98 on three tests. Which inequality can be used to find the score $G$ he must earn on the fourth test so that his average test score is at least 90?', NULL, '{"A":"$\\frac{85 + 78 + 98}{3} + G \\ge 90$","B":"$\\frac{85 + 78 + 98 + G}{4} \\ge 90$","C":"$\\frac{85 + 78 + 98 + G}{4} \\le 90$","D":"$\\frac{G}{4} + 85 + 78 + 98 \\ge 90$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('68f2cbaf', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'Ty walks at a speed of 4 kilometers per hour. He has a goal of walking at least 24 kilometers. What is the minimum number of hours Ty must walk to meet his goal?', NULL, '{"A":"4","B":"6","C":"20","D":"28"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
