VALUES ('ee439cff', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Easy', 'Rhett drives at an average speed of 35 miles per hour for $r$ hours and Jessica drives at an average speed of 40 miles per hour for $j$ hours. Their combined distance driven is under 220 miles. Which inequality represents this situation?', NULL, '{"A":"$35r + 40j < 220$","B":"$35r + 40j > 220$","C":"$35r + 40j \\le 220$","D":"$35r + 40j \\ge 220$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
