INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('55ea82f3', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Hard', 'A team hosting an event to raise money for new uniforms plans to sell at least 140 tickets before this event and at least 220 tickets during this event to raise a total of at least $\$5{,}820$ from all tickets sold. The price of a ticket during this event is $\$3$ less than the price of a ticket before this event. Which inequality represents this situation, where $x$ is the price, in dollars, of a ticket sold during this event?', NULL, '{"A":"$140(x + 3) + 220x \\le 5{,}820$","B":"$140(x + 3) + 220x \\ge 5{,}820$","C":"$140(x - 3) + 220x \\le 5{,}820$","D":"$140(x - 3) + 220x \\ge 5{,}820$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('ee7b1de1', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Hard', 'A small business owner budgets $\$2{,}200$ to purchase candles. The owner must purchase a minimum of 200 candles to maintain the discounted pricing. If the owner pays $\$4.90$ per candle to purchase small candles and $\$11.60$ per candle to purchase large candles, what is the maximum number of large candles the owner can purchase to stay within the budget and maintain the discounted pricing?', NULL, NULL, NULL, NULL, 'SPR', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
