INSERT INTO public.cb_questions (id, section, domain, cb_skill, difficulty, stem, passage, options, correct_answer, explanation, item_type, assets, source_ref)
VALUES ('6c71f3ec', 'M', 'Algebra', 'Linear inequalities in one or two variables', 'Hard', 'A salesperson''s total earnings consist of a base salary of $x$ dollars per year, plus commission earnings of 11% of the total sales the salesperson makes during the year. This year, the salesperson has a goal for the total earnings to be at least 3 times and at most 4 times the base salary. Which of the following inequalities represents all possible values of total sales $s$, in dollars, the salesperson can make this year in order to meet their goal?', NULL, '{"A":"$2x \\le s \\le 3x$","B":"$\\frac{2}{0.11}x \\le s \\le \\frac{3}{0.11}x$","C":"$3x \\le s \\le 4x$","D":"$\\frac{3}{0.11}x \\le s \\le \\frac{4}{0.11}x$"}'::jsonb, NULL, NULL, 'MCQ', NULL, '{"corpus":"official-cb","file":"linear-inequalities-in-one-or-two-variables.ndjson"}'::jsonb);
